// Differential harness: run the frozen Python executable and the Node port on
// the same argv and report any divergence.
//
// Usage:
//   node /tmp/harness/diff.mjs '<json-array-of-argv>'          # one case
//   node /tmp/harness/diff.mjs --file cases.json               # many cases
//
// cases.json is a JSON array whose entries are either argv arrays or
// {name, argv} objects. Exit status is 1 if any case diverged.
//
// Argv entries may use \uXXXX escapes to carry arbitrary characters. A NUL
// byte cannot survive execve(), so such cases are skipped.

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const PY = '/workspace/dataset/test6_executable';
const JS = '/output/test6.mjs';

// The PyInstaller banner embeds the pid, which necessarily differs run to run.
function normalise(text) {
  return text.replace(/\[PYI-\d+:/g, '[PYI-N:');
}

function run(command, argv) {
  const result = spawnSync(command[0], [...command.slice(1), ...argv], {
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  return {
    status: result.status,
    stdout: result.stdout ?? '',
    stderr: normalise(result.stderr ?? ''),
  };
}

function hasNul(token) {
  for (let i = 0; i < token.length; i += 1) {
    if (token.charCodeAt(i) === 0) return true;
  }
  return false;
}

function describe(argv) {
  return argv.map((token) => JSON.stringify(token)).join(' ');
}

const [first, second] = process.argv.slice(2);
const cases =
  first === '--file' ? JSON.parse(readFileSync(second, 'utf8')) : [JSON.parse(first)];

let failures = 0;
let skipped = 0;
for (const entry of cases) {
  const argv = Array.isArray(entry) ? entry : entry.argv;
  const name = Array.isArray(entry) ? describe(argv) : entry.name;
  if (argv.some(hasNul)) {
    skipped += 1;
    console.log(`SKIP  ${name}  (NUL cannot pass through execve)`);
    continue;
  }
  const py = run([PY], argv);
  const js = run(['node', JS], argv);
  if (py.status === js.status && py.stdout === js.stdout && py.stderr === js.stderr) continue;
  failures += 1;
  console.log(`FAIL  ${name}`);
  console.log(`  argv: ${describe(argv)}`);
  console.log(`  py  rc=${py.status} out=${JSON.stringify(py.stdout)} err=${JSON.stringify(py.stderr)}`);
  console.log(`  js  rc=${js.status} out=${JSON.stringify(js.stdout)} err=${JSON.stringify(js.stderr)}`);
}
console.log(`\n${cases.length - failures - skipped}/${cases.length} matched, ${failures} failed, ${skipped} skipped`);
process.exit(failures > 0 ? 1 : 0);

// Port of test6.py: bencode a nested list built from the command line, then
// decode it back and print both forms.

import { ArgumentParser, ArgumentError, ArgumentParserError, STR, INT } from './lib/argparse/index.mjs';
import * as bencoder from './lib/bencode/index.mjs';
import { encodeAscii } from './lib/python/codecs.mjs';
import { PythonError, SystemExit } from './lib/python/errors.mjs';
import { pyRepr } from './lib/python/repr.mjs';
import { reportUnhandled } from './lib/python/traceback.mjs';
import { printLine, exitWith, scriptArgs } from './lib/python/sys.mjs';

// The frozen executable reports itself under this name in usage and errors.
const PROG = 'test6_executable';
const SOURCE_FILE = 'test6.py';
const SCRIPT_NAME = 'test6';

// The line the encode() call sits on in the original source, quoted by the
// traceback when --a carries a non-ASCII character.
const ENCODE_LINE = 9;

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--a', { type: STR, required: true });
  parser.addArgument('--b', { type: INT, required: true });
  return parser;
}

function main() {
  const parser = buildParser();
  let args;
  try {
    args = parser.parseArgs(scriptArgs());
  } catch (error) {
    // argparse funnels both failure kinds through parser.error(), which prints
    // usage and exits 2.
    if (error instanceof ArgumentError || error instanceof ArgumentParserError) {
      parser.error(error.message);
    }
    throw error;
  }

  const listData = [encodeAscii(args.a), args.b, [args.b]];
  const encoded = bencoder.encode(listData);
  const decoded = bencoder.decode(encoded);
  printLine(pyRepr(encoded));
  printLine(pyRepr(decoded));
}

try {
  main();
} catch (error) {
  if (error instanceof SystemExit) {
    exitWith(error.code);
  } else if (error instanceof PythonError) {
    reportUnhandled(error, {
      fileName: SOURCE_FILE,
      lineNumber: ENCODE_LINE,
      scriptName: SCRIPT_NAME,
    });
    exitWith(1);
  } else {
    throw error;
  }
}
=====REPR=====
// Python's repr() for the value shapes this program prints.

import { PyBytes } from './bytes.mjs';
import { isPrintable } from '../unicode/properties.mjs';

// repr prefers single quotes, switching to double only when that avoids
// escaping — i.e. when the value contains ' but no ".
function pickQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

// The only mnemonic escapes repr emits. Notably \v, \f, \a and \b are *not*
// among them; those fall through to \xHH.
const MNEMONIC_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

function hexEscape(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function reprBytes(value) {
  const { codes } = value;
  const quote = pickQuote(codes.includes(0x27), codes.includes(0x22));
  const quoteCode = quote.charCodeAt(0);
  let out = `b${quote}`;
  for (const code of codes) {
    const mnemonic = MNEMONIC_ESCAPES.get(code);
    if (mnemonic !== undefined) out += mnemonic;
    else if (code === quoteCode) out += `\\${quote}`;
    else if (code < 0x20 || code >= 0x7f) out += hexEscape(code);
    else out += String.fromCharCode(code);
  }
  return out + quote;
}

export function reprStr(text) {
  const quote = pickQuote(text.includes("'"), text.includes('"'));
  let out = quote;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    const mnemonic = MNEMONIC_ESCAPES.get(codePoint);
    if (mnemonic !== undefined) out += mnemonic;
    else if (ch === quote) out += `\\${quote}`;
    else if (!isPrintable(ch)) out += hexEscape(codePoint);
    else out += ch;
  }
  return out + quote;
}

export function reprInt(value) {
  return String(value);
}

// Containers delegate to repr for their members, exactly as Python does.
export function pyRepr(value) {
  if (value instanceof PyBytes) return reprBytes(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const entries = [];
    for (const [key, item] of value) entries.push(`${pyRepr(key)}: ${pyRepr(item)}`);
    return `{${entries.join(', ')}}`;
  }
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

// The encoding half of bencode.

import { PyBytes } from '../python/bytes.mjs';
import { TypeError_ } from '../python/errors.mjs';

// Integers are written in canonical decimal with no size ceiling, so BigInt
// carries the value all the way to the wire.
function encodeInteger(value) {
  return PyBytes.fromLatin1(`i${value.toString()}e`);
}

// A byte string is its decimal length, a colon, then the raw octets.
function encodeByteString(value) {
  return PyBytes.concat([PyBytes.fromLatin1(`${value.length}:`), value]);
}

function encodeList(value) {
  const parts = [PyBytes.fromLatin1('l')];
  for (const item of value) parts.push(encodeValue(item));
  parts.push(PyBytes.fromLatin1('e'));
  return PyBytes.concat(parts);
}

// Dictionary keys are byte strings sorted by raw octet order, as bencode
// requires for a canonical encoding.
function encodeDict(value) {
  const entries = [...value.entries()];
  entries.sort(([left], [right]) => compareByteStrings(left, right));
  const parts = [PyBytes.fromLatin1('d')];
  for (const [key, item] of entries) {
    parts.push(encodeByteString(key));
    parts.push(encodeValue(item));
  }
  parts.push(PyBytes.fromLatin1('e'));
  return PyBytes.concat(parts);
}

function compareByteStrings(left, right) {
  const shared = Math.min(left.length, right.length);
  for (let index = 0; index < shared; index += 1) {
    if (left.codes[index] !== right.codes[index]) {
      return left.codes[index] - right.codes[index];
    }
  }
  return left.length - right.length;
}

export function encodeValue(value) {
  if (value instanceof PyBytes) return encodeByteString(value);
  if (typeof value === 'bigint') return encodeInteger(value);
  if (typeof value === 'boolean') return encodeInteger(value ? 1n : 0n);
  if (Array.isArray(value)) return encodeList(value);
  if (value instanceof Map) return encodeDict(value);
  throw new TypeError_(`Allowed types: bytes, int, list, dict; not ${typeof value}`);
}
=====DECODE=====
// The decoding half of bencode.

import { PyBytes } from '../python/bytes.mjs';
import { ValueError } from '../python/errors.mjs';

const COLON = 0x3a;
const MARKER_INT = 0x69; // 'i'
const MARKER_LIST = 0x6c; // 'l'
const MARKER_DICT = 0x64; // 'd'
const MARKER_END = 0x65; // 'e'
const ZERO = 0x30;
const NINE = 0x39;
const MINUS = 0x2d;

function isDigitCode(code) {
  return code >= ZERO && code <= NINE;
}

// A cursor over the octets, so the recursive readers can share one position.
class Reader {
  constructor(bytes) {
    this.bytes = bytes;
    this.position = 0;
  }

  atEnd() {
    return this.position >= this.bytes.length;
  }

  peek() {
    if (this.atEnd()) throw new ValueError('Unexpected end of data');
    return this.bytes.codes[this.position];
  }

  take() {
    const code = this.peek();
    this.position += 1;
    return code;
  }

  expect(code, label) {
    if (this.take() !== code) throw new ValueError(`Expected ${label}`);
  }
}

// Reads decimal digits (with an optional leading minus) up to a terminator.
function readSignedDigitsUntil(reader, terminator, label) {
  let text = '';
  if (reader.peek() === MINUS) {
    text += '-';
    reader.position += 1;
  }
  while (!reader.atEnd() && reader.peek() !== terminator) {
    const code = reader.take();
    if (!isDigitCode(code)) throw new ValueError(`Invalid digit in ${label}`);
    text += String.fromCharCode(code);
  }
  reader.expect(terminator, label);
  if (text === '' || text === '-') throw new ValueError(`Empty ${label}`);
  return BigInt(text);
}

function readInteger(reader) {
  reader.expect(MARKER_INT, "'i'");
  return readSignedDigitsUntil(reader, MARKER_END, 'integer');
}

function readByteString(reader) {
  let lengthText = '';
  while (!reader.atEnd() && reader.peek() !== COLON) {
    const code = reader.take();
    if (!isDigitCode(code)) throw new ValueError('Invalid length prefix');
    lengthText += String.fromCharCode(code);
  }
  reader.expect(COLON, "':'");
  if (lengthText === '') throw new ValueError('Missing length prefix');
  const length = Number(lengthText);
  if (reader.position + length > reader.bytes.length) {
    throw new ValueError('Truncated byte string');
  }
  const value = reader.bytes.slice(reader.position, reader.position + length);
  reader.position += length;
  return value;
}

function readList(reader) {
  reader.expect(MARKER_LIST, "'l'");
  const items = [];
  while (reader.peek() !== MARKER_END) items.push(readValue(reader));
  reader.position += 1;
  return items;
}

// Insertion order is preserved, matching the OrderedDict bencode decoders
// hand back for a dictionary.
function readDict(reader) {
  reader.expect(MARKER_DICT, "'d'");
  const entries = new Map();
  while (reader.peek() !== MARKER_END) {
    const key = readByteString(reader);
    entries.set(key, readValue(reader));
  }
  reader.position += 1;
  return entries;
}

function readValue(reader) {
  const code = reader.peek();
  if (code === MARKER_INT) return readInteger(reader);
  if (code === MARKER_LIST) return readList(reader);
  if (code === MARKER_DICT) return readDict(reader);
  if (isDigitCode(code)) return readByteString(reader);
  throw new ValueError(`Unexpected marker '${String.fromCharCode(code)}'`);
}

export function decodeValue(bytes) {
  const reader = new Reader(bytes);
  const value = readValue(reader);
  if (!reader.atEnd()) throw new ValueError('Trailing data after value');
  return value;
}

